INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64106, 'spa', 'Profanar lo sagrado', 'Mateo 12:5 usa la forma presente activa en el argumento de Jesús sobre la ley del sábado: los sacerdotes por necesidad ''profanan'' el sábado mediante el servicio del templo pero no tienen culpa, estableciendo un principio de que la misericordia y el servicio del templo superan el estricto descanso sabático. Hechos 24:6 contiene el infinitivo en la acusación de que Pablo intentó ''profanar el templo'', un cargo grave que Pablo niega vigorosamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64107, 'spa', 'Beelzeboul', 'Título de Satanás como príncipe de los demonios, derivado del hebreo ba’al («señor») combinado con zebul («morada») o con un juego peyorativo sobre zebub («moscas»). Aparece siete veces en los Sinópticos (Mt 10:25; 12:24, 27; Mr 3:22; Lc 11:15, 18, 19), siempre en el contexto de adversarios que atribuyen los exorcismos de Jesús a un poder demoníaco. En Mateo 10:25, Jesús advierte que si al amo de casa lo llaman así, cuánto más a los suyos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64110, 'spa', 'Proyectil o dardo', 'Lucas 18:25 en algunos manuscritos lee ''ojo de aguja'' (belonēs) en el famoso dicho de Jesús sobre la dificultad de los ricos para entrar al reino de Dios, aunque la mayoría de los textos usan una palabra griega diferente para aguja. Efesios 6:16 claramente usa el plural para ''flechas encendidas'' que el escudo de la fe apaga—representando ataques espirituales, tentaciones y acusaciones del maligno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64112, 'spa', 'Tribu de Benjamín', 'Nombre propio del hijo menor de Jacob y de la tribu israelita descendiente de él, usado en el NT principalmente como marcador de linaje tribal judío. La autoidentificación de Pablo como benjaminita (Rom 11:1; Phil 3:5) señala sus credenciales israelitas impecables, mientras que Acts 13:21 recuerda al rey Saúl de esta tribu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64113, 'spa', 'Princesa herodiana', 'Princesa de la dinastía herodiana presente durante la defensa de Pablo ante Agripa II. Hechos 25:13 introduce a Βερνίκη llegando con Agripa para saludar a Festo. Hechos 25:23 describe su entrada con gran pompa en la sala de audiencias para escuchar el caso de Pablo. Hechos 26:30 concluye con el rey, el gobernador y Βερνίκη levantándose tras la defensa de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64114, 'spa', 'Ciudad de Berea', 'Hechos 17:10 registra que Pablo y Silas fueron enviados de noche a Berea, donde encontraron una audiencia más receptiva que en Tesalónica. Hechos 17:13 describe cómo judíos de Tesalónica vinieron a Berea para continuar oponiéndose al ministerio de Pablo. El nombre de la ciudad aparece en forma dativa en ambos versículos, manteniendo el uso estándar del caso griego para ubicación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64116, 'spa', 'Betania — Aldea en la ladera suroriental del Monte de los Olivos, a unos quince ', 'Betania — Aldea en la ladera suroriental del Monte de los Olivos, a unos quince estadios (aproximadamente tres kilómetros) de Jerusalén (Jn 11:18). Hogar de María, Marta y Lázaro (Jn 11:1; 12:1), lugar donde Jesús se alojaba durante la semana de la Pasión (Mt 21:17; Mc 11:11-12), escenario de la unción (Mc 14:3) y lugar de la Ascensión (Lc 24:50). En Jn 1:28 aparece una segunda Betania en la ribera oriental del Jordán, donde Juan bautizaba, distinguiéndose geográficamente de la aldea cercana a Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64118, 'spa', 'Belén (topónimo)', 'Nombre propio de un pueblo judeo que significa ''casa del pan'', ubicado al sur de Jerusalén. Es la ciudad ancestral de David y el lugar profetizado para el nacimiento del Mesías (Mi 5:2, citado en Mt 2:6). Las ocho apariciones neotestamentarias se concentran en los relatos del nacimiento (Mt 2:1, 5, 6, 8, 16; Lc 2:4, 15) y el debate mesiánico de Juan 7:42.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64119, 'spa', 'Betsaida', 'El nombre propio Betsaida (arameo «casa de pesca»), que identifica un pueblo junto al mar de Galilea estrechamente vinculado al ministerio galileo de Jesús. Aparece en oráculos de juicio (Mt 11:21; Lc 10:13), como punto geográfico para los discípulos al cruzar el lago (Mr 6:45), como lugar de la sanación de un ciego (Mr 8:22), como escenario del milagro de la multiplicación (Lc 9:10) y como ciudad natal de Felipe, Andrés y Pedro (Jn 1:44; 12:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64121, 'spa', 'Aldea del Domingo de Ramos', 'Este topónimo aparece exclusivamente en los relatos sinópticos del Domingo de Ramos (Mateo 21:1, Marcos 11:1, Lucas 19:29). Las traducciones multilingües conservan la transliteración griega con leves variaciones ortográficas, siguiendo la práctica habitual para nombres bíblicos de lugares. La etimología aramea vincula el sitio con el cultivo de higos, detalle significativo dado que Jesús maldijo una higuera poco después.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64122, 'spa', 'tribunal, sede de juicio — Tribunal, sede de juicio o plataforma oficial desde l', 'tribunal, sede de juicio — Tribunal, sede de juicio o plataforma oficial desde la cual se pronuncian veredictos legales y decretos reales. Este sentido arquitectónico y jurídico domina el uso neotestamentario, apareciendo once veces en los Evangelios, Hechos y Epístolas. Pilato se sentó en el βῆμα en el Enlosado (Jn 19:13) para pronunciar juicio sobre Jesús; Galión desestimó las acusaciones judías contra Pablo desde el βῆμα en Corinto (Hch 18:12-17). Teológicamente, Pablo habla de comparecer ante el tribunal de Dios y de Cristo (Ro 14:10; 2 Co 5:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64123, 'spa', 'un paso, medida de terreno — Un paso, zancada o palmo de terreno — el significad', 'un paso, medida de terreno — Un paso, zancada o palmo de terreno — el significado espacial original del cual se desarrolló el sentido judicial. Hch 7:5 cita la promesa de Dios a Abraham de que le daría la tierra, aunque en aquel momento no le dio ''ni siquiera un paso (βῆμα) de terreno'' donde pisar. El español traduce ''paso'', distinguiendo claramente este sentido del significado de tribunal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64126, 'spa', 'Violencia o fuerza', 'Fuerza corporal o compulsión violenta ejercida contra personas o cosas, especialmente en situaciones de conflicto o crisis. Todas las apariciones neotestamentarias están en Hechos: la contención cautelosa de la guardia del templo (5:26), los soldados cargando físicamente a Pablo entre una multitud amotinada (21:35), y el poder destructivo del oleaje destrozando un barco (27:41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64127, 'spa', 'Violencia o esfuerzo forzoso', 'Mateo 11:12 usa la forma pasiva: ''el reino de los cielos biazetai''—ya sea ''sufre violencia'' de los oponentes o ''avanza con fuerza'' en poder. Lucas 16:16 declara ''todos biazetai en él''—ya sea ''se abren paso a la fuerza'' con determinación ansiosa o ''intentan forzarlo'' mediante violencia. Las traducciones preservan ambas posibilidades activa y pasiva. La gramática griega permite esta ambigüedad interpretativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64130, 'spa', 'Rollo profético pequeño', 'Las tres apariciones se encuentran en Apocalipsis 10:2, 9, 10, describiendo el rollo que Juan debe consumir proféticamente. El español «librito» preserva la fuerza diminutiva del término griego βιβλαρίδιον. El acto de comer el rollo simboliza la interiorización de la revelación profética, cuya experiencia mixta de dulzura y amargura refleja la naturaleza dual del mensaje divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64131, 'spa', 'libro, rollo, documento escrito', 'libro, rollo, documento escrito');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64137, 'spa', 'Libro / rollo (documento escrito)', 'Libro / rollo (documento escrito). Documento escrito en forma de rollo o codice, que generalmente se refiere a la Escritura sagrada o a una obra literaria autoritativa. Se usa para el libro de los Salmos (Lucas 20:42; Hechos 1:20), el registro genealogico (Mateo 1:1), el libro del profeta Isaias (Lucas 3:4) y el rollo celestial sellado con siete sellos (Apocalipsis 5:1-5). En Filipenses 4:3 se extiende al metaforico ''libro de la vida''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64141, 'spa', 'Provincia de Bitinia', 'Hechos 16:7 registra que Pablo y sus compañeros intentaron entrar en Bitinia pero fueron impedidos por el Espíritu de Jesús, una redirección divina que llevó a la visión macedónica y la entrada del evangelio a Europa. 1 Pedro 1:1 se dirige a exiliados electos ''de Bitinia'' (entre otras provincias), confirmando que el cristianismo sí se estableció allí a pesar de la prohibición divina anterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64142, 'spa', 'Vida, manera de vivir', 'Vida, manera de vivir. Vida entendida como existencia terrenal, experiencia cotidiana o manera de vivir — no la vida eterna o espiritual (que es zoe), sino el curso y la calidad de la existencia temporal. Jesus advierte que los espinos representan ''los afanes de esta vida'' (Lucas 8:14), y Pablo ora por ''una vida tranquila y apacible'' (1 Timoteo 2:2). La mujer con hemorragia gasto toda su ''vida'' buscando una cura (Lucas 8:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64144, 'spa', 'Sustento, posesiones, medios de vida', 'Sustento, posesiones, medios de vida. Sustento, posesiones materiales o medios de subsistencia — lo que uno tiene para vivir, y no el vivir en si. El hijo prodigo malgasto su ''hacienda'' (Lucas 15:12, 30), y la viuda pobre echo ''todo el sustento que tenia'' (Marcos 12:44; Lucas 21:4). El espanol diferencia esta acepcion con ''bienes'' (posesiones) y ''sustento'' junto al general ''vida'', y 1 Juan 3:17 alude a los ''bienes del mundo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64149, 'spa', 'Asuntos de esta vida', 'En 1 Corintios 6:3-4, Pablo usa el término dos veces para describir disputas sobre «asuntos ordinarios» o «cosas de esta vida», argumentando que si los creyentes juzgarán a los ángeles, con mayor razón pueden resolver conflictos cotidianos. Lucas 21:34 advierte contra dejarse consumir por «los afanes de esta vida». Las traducciones multilingües muestran consistencia: español «cosas de esta vida», francés «fosse», reflejando la misma imagen de lo terrenal frente a lo espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64151, 'spa', 'No dañar sobrenaturalmente', 'Marcos 16:18 usa el subjuntivo aoristo en la promesa de Jesús de que cosas mortales (incluyendo veneno) ''no dañarán'' a los creyentes, parte de las señales que siguen a quienes creen. Lucas 4:35 describe cómo el demonio, a pesar de arrojar violentamente al hombre al suelo, partió ''no habiéndole dañado en absoluto'' (participio aoristo activo con negación). El español ''dañará/habiendo dañado'', el francés ''nuire'' y el alemán ''schaden'' transmiten el concepto de causar perjuicio físico o deterioro funcional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64152, 'spa', 'Brotar o germinar', 'Producir brotes, yemas o retoños —la aparición visible de nuevo crecimiento vegetal desde la semilla o la rama. Usado literalmente para cultivos que brotan en las parábolas agrícolas de Jesús (Matt 13:26; Mark 4:27), para la vara de Aarón que brotó milagrosamente como validación divina (Heb 9:4), y para la tierra produciendo fruto al cesar la sequía (Jas 5:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64154, 'spa', 'blasfemar, hablar con irreverencia', 'blasfemar, hablar con irreverencia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64158, 'spa', 'ser blasfemado, ser difamado', 'ser blasfemado, ser difamado');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64174, 'spa', 'injuriar, calumniar a una persona', 'injuriar, calumniar a una persona');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64177, 'spa', 'Discurso que profana, injuria o difama — dirigido ya sea contra Dios (blasfemia ', 'Discurso que profana, injuria o difama — dirigido ya sea contra Dios (blasfemia propiamente dicha) o contra seres humanos (difamación, ultraje). La enseñanza de Jesús sobre el pecado imperdonable contra el Espíritu Santo (Mt 12:31; Mc 3:28-29) confiere a este término su filo teológico más agudo. También aparece en la acusación del sumo sacerdote durante el juicio de Jesús (Mt 26:65), en catálogos de vicios que exhortan a los creyentes a abandonar el lenguaje abusivo (Ef 4:31; Col 3:8), y en Apocalipsis como el discurso arrogante de la bestia contra Dios (Ap 13:1, 5-6). El español ''blasfemia'' preserva el sentido de ultraje sacrílego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64184, 'spa', 'Blasfemo o calumnioso', 'Que habla de manera injuriosa o sacrílega, ya sea contra Dios o contra personas; también usado como sustantivo para quien profiere tales palabras. Abarca la confesión de blasfemia pasada (1 Tim 1:13), testimonios blasfemos fabricados (Hch 6:11), un rasgo de los últimos tiempos (2 Tim 3:2) y el hablar temerario que los ángeles evitan (2 Pe 2:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64186, 'spa', 'ver, percibir visualmente', 'El sentido básico de vista física, con 74 apariciones. Mateo 13:13–14 cita la paradoja de Isaías: ''viendo no ven''. Las traducciones emplean uniformemente ''ver/ve/voir/sehen''. Es el sentido predeterminado y no marcado: los ojos funcionando como deben, ya sea ante la mota en el ojo del hermano (Mt 7:3) o las obras de Cristo (Mt 11:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64188, 'spa', '¡mira! ¡ved! (imperativo)', 'Imperativo directivo sin advertencia: ''¡mira! ¡ved! ¡presten atención!'' Con 12 apariciones, dirige la atención hacia algo que se señala. Marcos 4:24 dice ''mirad lo que oís''; 1 Corintios 1:26 invita a los corintios a ''ver'' su vocación. La fuerza es pedagógica más que cautelar: ''observen esto'' en vez de ''guárdense de aquello''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64191, 'spa', 'guardarse, tener cuidado', 'Advertencia imperativa: ''guardaos, tened cuidado'', con 17 apariciones. Marcos 8:15 advierte contra la levadura de los fariseos; Marcos 13:5, 9 previene contra el engaño y la persecución. El árabe iḥdharū (احذروا), el coreano josimhara (조심하라) y el suajili jihadharini pasan de ''ver'' a ''estar en guardia'', reconociendo un acto de habla cautelar diferenciado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64196, 'spa', 'ser visible, ser visto', 'Voz media/pasiva: ''ser visible, ser visto'', con 8 apariciones. El contraste teológico clave de Pablo en 2 Corintios 4:18 — τὰ βλεπόμενα frente a τὰ μὴ βλεπόμενα (lo que se ve frente a lo invisible) — impulsa este sentido. El español ''cosas que se ven'' y la construcción participial confirman un significado estativo o pasivo: lo que se presenta a la vista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64198, 'spa', 'mirar, dirigir la mirada', 'Mirar intencionadamente: ''mirar, fijar la vista'', con 17 apariciones. Mateo 5:28 advierte sobre mirar a una mujer con codicia; Mateo 22:16 dice que Jesús no ''mira'' (es decir, no muestra parcialidad hacia) las apariencias. El español mirando y el suajili tazama distinguen esta mirada enfocada de la visión pasiva, enfatizando la atención visual deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64208, 'spa', 'contemplar, mirar fijamente', 'Contemplación sostenida en tiempo imperfecto: ''miraban, contemplaban fijamente'', con 3 apariciones. Marcos 5:31 pregunta quién tocó a Jesús mientras la multitud ''miraba''; Juan 13:22 presenta a los discípulos ''mirándose unos a otros'' con confusión. El aspecto imperfecto capta un compromiso visual continuo e intenso, no una mirada fugaz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64212, 'spa', 'ver, experimentar (profético)', 'Visión futura/profética: ''veréis'', con 2 apariciones (Mt 13:14; Hch 28:26), ambas citando Isaías 6:9. Aquí βλέπω se enmarca como experimentar o presenciar lo que Dios ha declarado. El español ''veréis'' y el alemán ''sieht'' vierten el tiempo futuro directamente, pero la cita de Isaías le confiere un filo irónico: ver sin comprender.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64236, 'spa', 'clamar, gritar en alta voz — Clamar con voz fuerte y resonante en proclamación p', 'clamar, gritar en alta voz — Clamar con voz fuerte y resonante en proclamación profética o apelación pública urgente. Anclado en la cita de Isaías 40:3 aplicada a Juan el Bautista: ''Voz del que clama en el desierto: Preparad el camino del Señor'' (Mt 3:3; Mc 1:3; Lc 3:4; Jn 1:23). También se usa para el clamor de angustia y súplica, como cuando un padre ruega por su hijo endemoniado (Lc 9:38), Jesús grita desde la cruz (Mc 15:34), y los salarios de los obreros defraudados ''claman'' al Señor de los ejércitos (Stg 5:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64242, 'spa', 'Ayuda práctica o divina', 'Hechos 27:17 describe a marineros usando ''ayudas'' (boētheiais)—muy probablemente cables o cuerdas—para asegurar su barco durante la tormenta que eventualmente naufragaría a Pablo en Malta. Este término náutico técnico muestra medidas prácticas de emergencia. Hebreos 4:16 promete que los creyentes ''hallarán gracia para ayuda oportuna'', usando la misma raíz para describir asistencia divina disponible en el trono de Dios. El español ''ayudas/socorro'' captura tanto el sentido técnico como el espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64243, 'spa', 'Ayudar, socorrer', 'Acudir en ayuda de alguien necesitado, auxiliar o socorrer. La etimología compuesta (βοή ''grito'' + θέω ''correr'') transmite vívidamente la idea de correr hacia el clamor de alguien. Aparece en súplicas de sanidad — el urgente ''¡ayúdame!'' de la mujer cananea (Mt 15:25) y el ''¡ayuda mi incredulidad!'' del padre (Mc 9:24) — así como en la visión del llamado macedónico (Hch 16:9) y la exhortación de Hebreos a acercarse al trono de la gracia (He 4:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64249, 'spa', 'Hoyo o foso', 'Mateo 12:11 emplea el hoyo en una controversia sobre el sábado al rescatar una oveja caída. Mateo 15:14 y Lucas 6:39 usan la misma advertencia proverbial sobre guías ciegos que conducen a otros ciegos hasta que ambos caen en un hoyo. El reconocimiento universal de este peligro se traduce de manera consistente en todas las lenguas, evocando la misma imagen de trampa y caída.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64251, 'spa', 'Sondar profundidad marítima', 'Hechos 27:28 usa dos veces el participio aoristo activo ''habiendo sondeado'' para describir las mediciones repetidas de profundidad de los marineros mientras derivaban hacia la costa de Malta. Primero encontraron veinte brazas, luego después de un poco quince brazas—mostrando su peligroso acercamiento a la costa en oscuridad. La precisión técnica del relato (mediciones exactas de profundidad) añade autenticidad a la narrativa de Lucas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64252, 'spa', 'Nombre propio bíblico', 'El nombre aparece dos veces en Mateo 1:5 (como padre e hijo en la genealogía) y una vez en Lucas 3:32. El nombre hebreo בֹּעַז probablemente significa «en él hay fuerza». Las glosas multilingües muestran variaciones ortográficas menores al transliterar el nombre; el griego conserva dos formas (Βοός, Βοές), mientras que las traducciones modernas estandarizan como Booz. Su inclusión en la genealogía a través de Rut destaca la acogida divina de los gentiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64254, 'spa', 'Dirección norte', 'Lucas 13:29 incluye ''norte'' en la lista direccional cuádruple de Jesús (este, oeste, norte, sur) describiendo la reunión universal de los salvos desde todos los rincones de la tierra a la mesa de Abraham. Apocalipsis 21:13 especifica las puertas del norte de la Nueva Jerusalén en su descripción arquitectónica completa. El español ''norte'', el francés ''nord'' y el alemán ''Norden'' proveen términos direccionales directos. Ambos pasajes usan el término para indicar inclusividad geográfica exhaustiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64255, 'spa', 'Alimentar, apacentar (activa)', 'Alimentar o apacentar como pastor: el trabajo activo de cuidar animales o, metafóricamente, personas encomendadas al propio cuidado. Los porquerizos apacentaban (βόσκοντες) cerdos cerca del mar de Galilea (Mt 8:33; Mr 5:14; Lc 8:34), y el hijo pródigo fue enviado a apacentar (βόσκειν) cerdos en tierra lejana (Lc 15:15). El mandato de Jesús a Pedro, ''Apacienta (βόσκε) mis corderos'' (Jn 21:15), eleva el término del pastoreo literal al espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64256, 'spa', 'Pacer, pastar (media/pasiva)', 'Pacer o estar pastando, dicho de los animales mismos en voz media o pasiva, describiendo al ganado alimentándose en un campo o ladera. Una gran piara de cerdos estaba paciendo (βοσκομένη) en el monte cuando los demonios pidieron entrar en ellos (Mt 8:30; Mr 5:11; Lc 8:32). El cambio de voz activa (el pastor alimenta) a media/pasiva (los animales se alimentan) refleja una distinción natural de voz griega.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64265, 'spa', 'Miembro del Sanedrín', 'Marcos 15:43 y Lucas 23:50 ambos identifican a José de Arimatea como ''un consejero'' (bouleutēs), significando un miembro del Sanedrín que había condenado a Jesús. Lucas añade que era ''un hombre bueno y justo'' que no había consentido a su decisión. El español ''consejero/miembro del concejo'', el francés ''conseiller'' y el alemán ''Ratsherr'' transmiten membresía en un cuerpo deliberativo oficial. El término destaca la posición social elevada de José y el riesgo que tomó.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64266, 'spa', 'Deliberar, planear', 'Deliberar, tomar consejo o resolver un curso de acción tras sopesar las opciones. La voz media subraya una toma de decisión personal y meditada. Un rey se sienta a deliberar antes de marchar a la guerra (Lucas 14:31), modelo de evaluación prudente. El consejo judío resolvió matar tanto a Jesús (Juan 11:53) como a Lázaro (Juan 12:10), mostrando deliberación que conduce a un veredicto siniestro. Pablo apela a este verbo para defender la seriedad de sus intenciones (2 Co 1:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64270, 'spa', 'Plan soberano, decreto o propósito de Dios — su voluntad determinada respecto a ', 'Plan soberano, decreto o propósito de Dios — su voluntad determinada respecto a la historia de la salvación. Central en la teología de Lucas-Hechos: la βουλή de Dios entregó a Jesús a la crucifixión (Hch 2:23; 4:28), abarca todo el alcance del evangelio (Hch 20:27) y constituye el criterio frente al cual se mide la aceptación o el rechazo humano (Lc 7:30). Efesios 1:11 habla de Dios que obra todas las cosas conforme al consejo de su voluntad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64278, 'spa', 'Voluntad o propósito', 'Hechos 27:43 describe el «propósito» del centurión de salvar a Pablo. Romanos 9:19 plantea la pregunta retórica sobre resistir la voluntad de Dios en el contexto de la elección soberana. 1 Pedro 4:3 se refiere al «deseo» o «voluntad» de los gentiles que caracterizaba la vida anterior de los creyentes. Las traducciones al español distinguen entre «deseo», «propósito» y «voluntad», reflejando los distintos matices del término según el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64279, 'spa', 'querer, desear', 'querer, desear');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64281, 'spa', 'determinar, decretar', 'determinar, decretar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64291, 'spa', 'proponerse, planear', 'proponerse, planear');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64300, 'spa', 'Colina topográfica', 'Lucas 3:5 cita Isaías 40:4, incluyendo ''toda colina'' entre las características del paisaje que serán niveladas en preparación para la venida del Señor—una metáfora para remover obstáculos y preparar corazones. Lucas 23:30 cita Oseas 10:8, donde personas aterradas por el juicio clamarán a las colinas para que les cubran de la ira de Dios. Las traducciones al español como ''colina/collados'', francés ''colline'' y alemán mantienen este significado topográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64301, 'spa', 'Buey, ganado bovino', 'Un bovino doméstico —buey, toro o vaca— que aparece en contextos agrícolas, legales, sacrificiales y proverbiales del NT. Jesús menciona bueyes en controversias sobre el sábado (Lc 13:15; 14:5) y en la excusa del invitado que compró cinco yuntas de bueyes (Lc 14:19). La purificación del templo involucra vendedores de bueyes (Jn 2:14-15). La cita paulina de ''no pondrás bozal al buey'' (1 Co 9:9; 1 Ti 5:18) fundamenta el derecho al sustento ministerial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64306, 'spa', 'Premio atlético', '1 Corintios 9:24 usa la metáfora del concurso atlético: todos los corredores compiten pero solo uno recibe ''el premio'', instando a los cristianos a correr de manera que asegure la victoria. Filipenses 3:14 describe a Pablo ''prosiguiendo hacia la meta al premio'' del llamamiento celestial de Dios, enfatizando el impulso hacia adelante y la búsqueda enfocada. Las traducciones al español ''premio'', francés ''prix'' y alemán ''Preis'' todas mantienen el significado de recompensa/galardón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64308, 'spa', 'Tardar o demorarse', '1 Timoteo 3:15 usa el subjuntivo presente: ''si me tardare'' (o ''fuere demorado''), mostrando la conciencia de Pablo de que sus planes de viaje podrían no materializarse rápidamente, necesitando orientación escrita para la iglesia. 2 Pedro 3:9 usa el indicativo activo presente en una declaración teológica: el Señor ''no tarda'' respecto a su promesa de regreso, reenmarcando la aparente demora como misericordia paciente. El español ''tarda/tardo'' captura esta idea de retraso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64310, 'spa', 'Lento o tardo', 'Lucas 24:25 registra la reprensión de Jesús: «¡Oh insensatos y tardos de corazón para creer!». Santiago 1:19 aparece dos veces en el mismo versículo, aconsejando a los creyentes ser «tardos para hablar, tardos para la ira». La evidencia multilingüe es consistente: español «lento/lentos», francés «lent», alemán «langsam», todos transmitiendo el sentido básico de lentitud. El contexto determina si esta lentitud es un defecto o una virtud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64312, 'spa', 'Brazo divino', 'Lucas 1:51 recoge el cántico de María: «Hizo proezas con su brazo». Juan 12:38 cita Isaías 53:1: «¿A quién se ha revelado el brazo del Señor?» Hechos 13:17 describe cómo Dios «con brazo levantado los sacó» de Egipto. En los tres contextos el brazo simboliza el poder y la liberación divinos. Las traducciones conservan uniformemente el término anatómico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64313, 'spa', 'Poco, corto, breve', 'Pequeño en cantidad, duración o extensión; se usa tanto adverbial como adjetivalmente para expresar brevedad o pequeñez. Abarca cortedad temporal (Lucas 22:58, «después de un poco»; Hechos 5:34, Gamaliel pide que los apóstoles salgan «por un poco de tiempo»), brevedad espacial (Hechos 27:28, «un poco más adelante»), y pequeñez cuantitativa (Juan 6:7, doscientos denarios no bastarían para que cada uno recibiera «un poco»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64317, 'spa', 'Bebé, infante (persona)', 'Un bebé, infante o niño por nacer como persona concreta. Abarca al niño que salta en el vientre (Lc 1:41, 44), al recién nacido envuelto en pañales (Lc 2:12, 16) y a los infantes traídos a Jesús (Lc 18:15). El referente es siempre un ser humano muy pequeño y dependiente, ya sea prenatal o recién nacido, que necesita protección y cuidado absolutos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64318, 'spa', 'Infancia (etapa de vida)', 'El período o etapa de la infancia, usado de manera abstracta y no como referencia a un niño concreto. En 2 Timoteo 3:15 Pablo escribe que Timoteo ha conocido las Sagradas Escrituras ''desde la infancia'' (ἀπὸ βρέφους), donde la palabra denota la fase más temprana de la vida. El español ''infancia'' capta este uso temporal y abstracto, en contraste con el concreto ''bebé'' empleado en otros pasajes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64322, 'spa', 'Mojar, humedecer', 'Mojar o humedecer con un líquido que no es lluvia: un sentido físico y corporal usado exclusivamente en el relato lucano de la mujer pecadora en la cena del fariseo. En Lucas 7:38 ella «comenzó a mojar» (βρέχειν) los pies de Jesús con sus lágrimas, y en 7:44 Jesús contrasta su devoción con la negligencia del anfitrión: «ella mojó (ἔβρεξεν) mis pies con lágrimas». El paso de «llover» a «mojar» señala la transición semántica de lo celeste a lo íntimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64323, 'spa', 'Llover, enviar lluvia', 'Llover o enviar lluvia: el sentido meteorológico que describe la precipitación que cae del cielo, ya sea lluvia ordinaria o juicio divino. Cinco apariciones abarcan todo el rango teológico: Dios «hace llover» (βρέχει) sobre justos e injustos (Mt 5:45), Dios «hizo llover» (ἔβρεξεν) fuego y azufre sobre Sodoma (Lc 17:29), y Elías oró para que el cielo «no lloviese» (οὐκ ἔβρεξεν) durante tres años y medio (Stg 5:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64329, 'spa', 'Trueno como manifestación teofánica del poder divino y la majestad celestial', 'Trueno como manifestación teofánica del poder divino y la majestad celestial. Predomina en el Apocalipsis, donde procede del trono de Dios (Ap 4:5; 8:5; 11:19; 16:18), acompaña la apertura de los sellos del Cordero (Ap 6:1) y confiere peso cósmico a las proclamaciones angélicas (Ap 10:3-4; 14:2; 19:6). En Juan 12:29 la voz del Padre desde el cielo es confundida con un trueno por la multitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64334, 'spa', 'Lluvia literal', 'Mateo 7:25 describe cómo ''descendió la lluvia'' como parte de la tormenta probando la casa edificada sobre roca, que permaneció firme. Mateo 7:27 usa lenguaje idéntico para la tormenta probando la casa sobre arena, que cayó. El español ''lluvia'', francés ''pluie'' y alemán todos proveen el término directo para lluvia. La repetición de la palabra en la misma parábola enfatiza que ambos constructores enfrentaron condiciones idénticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64336, 'spa', 'Crujir de dientes', 'El acto de crujir o rechinar los dientes, que expresa angustia extrema, ira o desesperación. Aparece exclusivamente en la frase formulaica «el llanto y el crujir de dientes» (ὁ κλαυθμὸς καὶ ὁ βρυγμὸς τῶν ὀδόντων), que Jesús emplea para describir el tormento de quienes son arrojados a las tinieblas de afuera o al horno de fuego (Mt 8:12; 13:42, 50; 22:13; 24:51; 25:30; Lc 13:28). Todos los idiomas de destino lo traducen con un término que evoca fricción dental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64339, 'spa', 'Lo que se come, alimento sólido o sustento', 'Lo que se come, alimento sólido o sustento. Las diecisiete apariciones en el NT comparten el mismo significado central de sustento comestible. En contextos literales se refiere a provisiones para multitudes o comidas diarias (Lc 3:11, Mt 14:15). En el discurso teológico se convierte en vehículo para discutir lo que contamina (Mr 7:19), los límites de la libertad cristiana respecto a alimentos ofrecidos a ídolos (1 Co 8:8, 13), y la distinción paulina entre leche y alimento sólido como metáfora de madurez espiritual (1 Co 3:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64348, 'spa', 'Alimento', 'Alimento. Alimento o sustento como sustancia para ser consumida. Es la acepcion dominante en el Evangelio de Juan, donde Jesus habla del verdadero alimento (βρῶσις) que permanece para vida eterna (Juan 6:27, 55). Las traducciones multilingues la rinden consistentemente como sustento: espanol ''alimento/comida'', frances ''nourriture'', aleman ''Speise'' — todas enfatizando la provision mas que el acto de consumo. Tambien en 2 Corintios 9:10 donde Dios provee el alimento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64350, 'spa', 'Deterioro, corrosion', 'Deterioro, corrosion. Corrosion, herrumbre o deterioro que destruye los bienes materiales. Se limita a la ensenanza de Jesus sobre los tesoros en Mateo 6:19-20, donde βρῶσις se empareja con la polilla (σής) como agentes de destruccion. El espanol ''herrumbre'' capta bien esta acepcion. La palabra describe el lento e implacable consumo de la riqueza terrenal — una vivida metafora que urge a acumular tesoros en el cielo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64351, 'spa', 'Accion de comer', 'Accion de comer. El acto o proceso de comer, enfatizando la actividad mas que la sustancia consumida. En Romanos 14:17, Pablo declara que el reino de Dios no es comida (βρῶσις) ni bebida, donde el espanol ''comer'' emplea la forma verbal destacando la accion. De igual modo en 1 Corintios 8:4 respecto a comer alimentos ofrecidos a los idolos, el enfoque recae sobre la practica misma y sus implicaciones teologicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64354, 'spa', 'Hundirse o sumergir', 'Lucas 5:7 usa el infinitivo presente medio/pasivo para describir los botes ''comenzando a hundirse'' por la pesca sobreabundante después del mandato de Jesús—un milagro físico que provocó la confesión de Pedro. 1 Timoteo 6:9 emplea el indicativo activo presente: quienes desean ser ricos ''hunden a las personas en ruina y destrucción'', con algunos manuscritos leyendo el pasivo ''son hundidos''. El español ''hunden/hundirse'' captura ambos sentidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64356, 'spa', 'Curtidor de pieles', 'Las tres apariciones en Hechos 9:43, 10:6 y 10:32 se refieren a Simón el curtidor, anfitrión de Pedro en Jope. La narración destaca que su casa estaba «junto al mar», probablemente porque los talleres de curtido se ubicaban cerca del agua para el proceso de curado y a sotavento de las zonas residenciales por los olores desagradables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64357, 'spa', 'De lino fino', 'Describe prendas o telas hechas de biso (lino fino). Sus cinco apariciones neotestamentarias se concentran en Apocalipsis, donde funciona como marcador de lujo en los bienes de Babilonia (Ap 18:12, 16) y luego simboliza pureza y justicia en la vestidura nupcial de los santos (Ap 19:8) y la indumentaria celestial (Ap 19:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64361, 'spa', 'El arcángel Gabriel', 'Lucas 1:19 registra la auto-presentación de Gabriel ante Zacarías: ''Yo soy Gabriel, que estoy en la presencia de Dios, y fui enviado a hablarte''. Lucas 1:26 declara que ''el ángel Gabriel fue enviado por Dios'' a Nazaret para anunciar el nacimiento de Jesús a María. El español y el inglés mantienen ''Gabriel'', el francés ''Gabriel'', y el alemán ''Γαβριήλ'' preservan la transliteración del nombre. Los mensajes de Gabriel marcan momentos cruciales en la historia de la salvación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64367, 'spa', 'Tesoro del templo', 'El tesoro del templo o receptáculo de ofrendas. En Marcos 12:41-43 y Lucas 21:1 designa los recipientes de recolección en el Atrio de las Mujeres donde los fieles depositaban sus contribuciones, escenario de la observación de Jesús sobre la ofrenda sacrificial de la viuda. En Juan 8:20 identifica un lugar específico dentro del recinto del templo donde Jesús enseñaba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64368, 'spa', 'Nombre propio cristiano', 'Nombre propio (del latín Gaius) llevado por varios cristianos primitivos. Aparece en cinco pasajes que abarcan desde el ministerio paulino hasta las epístolas juaninas. Era uno de los dieciocho praenomina romanos tradicionales, lo que lo hacía sumamente común en el mundo grecorromano. El español conserva la forma ''Gayo'', mientras que otras lenguas reflejan la grafía griega o latina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64369, 'spa', 'Leche, literal y figurada', 'Leche como alimento, en sentido literal y figurado. Literalmente, el producto lácteo del ganado, como en la pregunta de Pablo sobre el derecho del pastor (1 Co 9:7). Figuradamente, la enseñanza espiritual elemental para creyentes nuevos, contrastada con el ''alimento sólido'' para los maduros (1 Co 3:2; He 5:12-13). Pedro exhorta a desear esta leche pura para crecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64371, 'spa', 'Región de Asia Menor', 'Nombre geográfico de una región en el centro de Asia Menor, patria de tribus celtas asentadas y luego provincia romana más amplia. Pablo fundó congregaciones allí (Gál 1:2), organizó colectas entre ellas (1 Cor 16:1) y un colaborador viajó a esa zona (2 Tim 4:10). Primera de Pedro 1:1 se dirige a creyentes dispersos por esta provincia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64372, 'spa', 'región de Galacia', 'Hechos 16:6 describe a Pablo y sus compañeros pasando por ''la región de Frigia y Galacia'' después de ser impedidos de predicar en Asia, marcando la primera evangelización de Galacia por Pablo. Hechos 18:23 registra a Pablo durante su tercer viaje ''pasando por la región de Galacia y Frigia en orden, fortaleciendo a todos los discípulos''. El español ''gálata/la Gálata'', el francés ''Galate'', y las formas alemanas mantienen la transliteración, señalando las áreas específicas del ministerio itinerante de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64373, 'spa', 'Calma marítima', 'Las tres apariciones (Mateo 8:26, Marcos 4:39, Lucas 8:24) corresponden a los relatos sinópticos de Jesús calmando la tempestad. La estructura narrativa es idéntica: tormenta feroz, temor de los discípulos, reprensión de Jesús al viento y las olas, e inmediata «gran calma». Las glosas multilingües son uniformes, subrayando la quietud completa que sigue a la intervención milagrosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64374, 'spa', 'Galilea (region)', 'Nombre geografico propio de la region septentrional de Israel/Palestina, que abarca el area alrededor del mar de Galilea donde Jesus fue criado en Nazaret y realizo la mayor parte de su ensenanza y ministerio de milagros. La evidencia interlingüistica muestra una transliteracion uniforme en todos los idiomas, confirmando una unica identidad toponimica a lo largo de las 61 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64378, 'spa', 'Galileo', 'Galileo. Persona de la region de Galilea en el norte de Israel, usado como gentilicio propio. Se aplica a Jesus y a sus discipulos (Mateo 26:69; Marcos 14:70; Lucas 22:59, 23:6), a los apostoles en Pentecostes (Hechos 1:11; 2:7), a Judas el insurgente (Hechos 5:37) y a los adoradores ejecutados por Pilato (Lucas 13:1-2). El espanol ''galileo'', el aleman ''Galilaer'' y el hindi ''galili'' confirman una transliteracion uniforme en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64383, 'spa', 'Procónsul de Acaya', 'Las tres referencias se hallan en Hechos 18:12, 14 y 17, donde se narra el intento fallido de los judíos corintios de procesar a Pablo ante el procónsul. El dictamen de Galión, que calificó la disputa como cuestión de «palabras, nombres y vuestra propia ley», estableció un precedente legal importante para la misión cristiana primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64384, 'spa', 'el rabino Gamaliel', 'Hechos 5:34 introduce a Gamaliel como ''un fariseo llamado Gamaliel, maestro de la ley respetado por todo el pueblo'', quien luego pronuncia su famoso consejo instando paciencia con los apóstoles. Hechos 22:3 tiene a Pablo declarando que fue ''criado en esta ciudad, educado a los pies de Gamaliel según la estricta manera de la ley de nuestros padres''. El español ''Gamaliél/de Gamaliél'', las formas francesas, y el alemán preservan el nombre, marcando tanto la autoridad de Gamaliel en el Sanedrín como su influencia formativa sobre Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64385, 'spa', 'El sentido verbal activo', 'El sentido verbal activo: contraer matrimonio, tomar esposa o esposo. Pasajes clave incluyen la ensenanza de Jesus de que el nuevo matrimonio tras el divorcio constituye adulterio (Mt 19:9), la ensenanza escatologica de que en la resurreccion ni se casan ni se dan en casamiento (Mt 22:30), y el extenso consejo de Pablo sobre el matrimonio en 1 Corintios 7.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64390, 'spa', 'Sentido participial o estativo que designa a alguien en la condicion de estar ca', 'Sentido participial o estativo que designa a alguien en la condicion de estar casado. Pablo se dirige a estas personas especificamente en 1 Co 7:10 (''a los casados mando'') y describe las preocupaciones divididas del hombre casado (1 Co 7:33) y la mujer casada (1 Co 7:34), donde el participio funciona como designacion de estado civil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64401, 'spa', 'Dar en matrimonio', 'Dar en matrimonio, concertar una boda para alguien: el equivalente causativo de γαμέω (casarse). La voz activa implica el papel del padre o tutor que entrega a un hijo en matrimonio, mientras que la pasiva significa ''ser dado en casamiento''. Jesús lo emplea en dos contextos: describiendo la normalidad antes del diluvio, cuando ''se casaban y se daban en casamiento'' (Mt 24:38; Lc 17:27), y enseñando que en la resurrección no habrá tales uniones (Mt 22:30; Mr 12:25; Lc 20:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64406, 'spa', 'Una celebración nupcial o banquete de bodas, que abarca tanto el festín gozoso (', 'Una celebración nupcial o banquete de bodas, que abarca tanto el festín gozoso (Mt 22:2-14; Jn 2:1-2; Ap 19:7-9) como la institución matrimonial (Heb 13:4). En el uso parabólico, el banquete de bodas se convierte en imagen escatológica del reino: invitación, preparación y consumación final en las bodas del Cordero. Las 16 apariciones en el NT, ya sea en singular o plural, nominativo u oblicuo, giran en torno al vínculo festivo y pactual del matrimonio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64411, 'spa', 'conjunción causal-explicativa', 'Única función de γάρ: introducir la razón, causa, explicación o evidencia de lo dicho inmediatamente antes. Siempre en segunda posición (postpositiva). Estructura el razonamiento lógico y la argumentación retórica del texto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64412, 'spa', 'Vientre, entraña', 'El vientre o entraña como cavidad corporal interna, principalmente el útero en contextos de concepción y embarazo, y secundariamente el estómago como sede del apetito y la gula. La expresión ''ἐν γαστρὶ ἔχουσα'' (tener en el vientre) aparece en Mt 1:18, 23; 24:19; Mr 13:17; Lc 1:31; 21:23, abarcando la anunciación, la profecía isaiana y advertencias escatológicas para las embarazadas. En Tito 1:12 designa el estómago como emblema de glotonería.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64414, 'spa', 'Partícula enfática afirmativa que refuerza la verdad o certeza de la declaración', 'Partícula enfática afirmativa que refuerza la verdad o certeza de la declaración a la que se une: ''ciertamente, en verdad, de veras.'' Con 12 apariciones, esta es la función predeterminada de γε: confirmar lo que de otro modo podría parecer dudoso. En Hch 17:27 Pablo declara que Dios ''no está lejos de cada uno de nosotros,'' con γε subrayando la certeza. Lc 24:21 la emplea en la expresión nostálgica de los discípulos: ''esperábamos que él fuera...''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64417, 'spa', 'Partícula intensiva escalar que eleva o escala la fuerza de una palabra para sig', 'Partícula intensiva escalar que eleva o escala la fuerza de una palabra para significar ''incluso, aun,'' llevando el énfasis más allá de lo que el contexto por sí solo proporcionaría. El caso claro en el NT es Filipenses 3:8, donde Pablo escribe que tiene ''por pérdida todas las cosas ante el incomparable valor de conocer a Cristo Jesús mi Señor.'' El español ''aun'' captura esta fuerza ascendente con precisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64418, 'spa', 'Partícula restrictiva o concesiva que significa ''al menos, por lo menos,'' establ', 'Partícula restrictiva o concesiva que significa ''al menos, por lo menos,'' estableciendo un umbral mínimo aun cuando la afirmación más amplia pueda ser discutida. Tres apariciones llevan este matiz: la viuda persistente que obtendrá justicia ''al menos'' por su insistencia (Lc 18:5), el vecino que ayudará ''al menos'' por la importunidad (Lc 11:8), y la apelación de Pablo de que ''al menos para vosotros soy apóstol'' (1 Co 9:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64426, 'spa', 'El lugar escatológico de castigo y destrucción para los impíos, representado com', 'El lugar escatológico de castigo y destrucción para los impíos, representado como un ámbito de fuego inextinguible. Las doce ocurrencias neotestamentarias llevan este significado. Jesús advierte sobre ''la Gehenna de fuego'' (Mt 5:22; 18:9), la destrucción del cuerpo y el alma (Mt 10:28; Lc 12:5) y el fuego eterno preparado para la condenación (Mr 9:43, 45, 47). Se contrapone a la entrada en la vida o en el reino. Santiago 3:6 la aplica metafóricamente a la lengua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64428, 'spa', 'el huerto de Getsemaní', 'Mateo 26:36 registra a Jesús viniendo ''a un lugar llamado Getsemaní'' y diciéndoles a Sus discípulos que se sienten mientras Él ora. Marcos 14:32 usa lenguaje casi idéntico: ''vinieron a un lugar que se llamaba Getsemaní''. El español ''Getsemaní/Getsemaní'', el francés ''Gethsémané'', y el alemán ''Gethsemane/Γεθσημανί'' muestran ligera variación ortográfica al transliterar el arameo. Ambos relatos evangélicos nombran este lugar específico donde Jesús enfrentó la agonía de la sumisión antes de Su pasión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64429, 'spa', 'Vecino residencial', 'Persona que vive cerca, vecino del mismo barrio o comunidad, implicando relaciones comunitarias y familiaridad mutua. Lucas lo usa en contextos de celebración compartida (Lc 15:6, 9, vecinos que se regocijan por lo hallado) y obligación social (Lc 14:12, no invitar vecinos por reciprocidad). Juan 9:8 muestra a vecinos que reconocen a alguien por el trato diario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64430, 'spa', 'reír con gozo/burla', 'Lucas 6:21 concluye una bienaventuranza: ''Bienaventurados los que ahora lloráis, porque reiréis'' (futuro medio indicativo γελάσετε), prometiendo que el dolor presente se transformará en gozo. Lucas 6:25 comienza un ay: ''Ay de vosotros, los que ahora reís, porque lamentaréis y lloraréis'', advirtiendo que el gozo presente se revertirá en dolor. El español ''reiréis/que ríen'', el francés ''rire'', y el alemán ''γελάσετε/γελῶντες'' capturan tanto la promesa como la advertencia, enfatizando la reversión escatológica que Jesús proclama.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64432, 'spa', 'Llenar, ser llenado', 'Llenar completamente un recipiente o espacio con una sustancia, ya sea líquida, sólida o incluso oleaje. Las nueve apariciones en el NT involucran un llenado literal y físico: agua en las tinajas de Caná (Juan 2:7), fragmentos sobrantes en canastas (Juan 6:13), olas inundando una barca (Marcos 4:37), vinagre empapando una esponja (Marcos 15:36) y una casa llena de invitados en la parábola del gran banquete (Lucas 14:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64440, 'spa', 'Estar lleno, colmado de', 'Estar lleno, colmado de. Estar lleno, rebosante o cargado de algo fisico o moral. En sentido denunciatorio: copas ''llenas de'' avaricia (Mateo 23:25; Lucas 11:39), sepulcros ''llenos de'' huesos (Mateo 23:27), bocas ''llenas de'' maldicion (Romanos 3:14). En sentido apocaliptico: criaturas ''llenas de'' ojos (Apocalipsis 4:6, 8), copas ''llenas de'' oraciones como incienso (Apocalipsis 5:8) e ira divina (Apocalipsis 15:7; 17:3-4). El espanol ''lleno'' y el suajili ''imejaa'' confirman una traduccion uniforme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64444, 'spa', 'Generación (personas de una época / período de linaje)', 'Generación (personas de una época / período de linaje): Las personas que comparten una misma época, o el lapso de un eslabón genealógico. Jesús frecuentemente califica a «esta generación» con juicio moral (Mt 11:16; 12:39), mientras que Mateo 1:17 emplea el término para medir los intervalos de la historia de la salvación. El español «generación», el francés «génération» y el alemán «Geschlecht» confirman un sentido temporal-colectivo unificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64449, 'spa', 'Registro de linaje familiar', '1 Timoteo 1:4 advierte contra ''fábulas y genealogías interminables'' (γενεαλογίαις ἀπεράντοις) que promueven especulaciones en lugar de la mayordomía de Dios que es por fe. Tito 3:9 enumera ''genealogías'' junto con disputas necias y argumentos sobre la ley como cosas que se deben evitar. El español ''genealogías'', formas francesas y el alemán ''Geschlechtsregister'' todos hacen referencia a registros de ascendencia. Ambos pasajes tratan las genealogías como potencialmente divisivas cuando se usan para especulación sin provecho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64450, 'spa', 'Fiesta de cumpleaños', 'Mateo 14:6 declara que ''cuando se celebraba el cumpleaños (genesiois) de Herodes,'' la hija de Herodías bailó ante él, llevando a la ejecución de Juan. Marcos 6:21 describe ''un día oportuno'' llegando ''cuando Herodes en su cumpleaños (genesiois) hizo una cena'' para sus oficiales. El español ''cumpleaños'', francés ''anniversaire'' y alemán ''Geburtstag/γενεσίοις'' todos hacen referencia a celebraciones de cumpleaños. Ambos relatos presentan este cumpleaños como el escenario trágico del martirio de Juan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64451, 'spa', 'Origen, nacimiento, existencia', 'Origen, nacimiento o proceso de llegar a ser. Abarca el origen genealógico (Mt 1:1, donde ''biblos geneseōs'' evoca el Génesis), el evento físico del nacimiento (Mt 1:18; Lc 1:14) y el ciclo de la existencia natural (Stg 1:23, apariencia natural; Stg 3:6, ''la rueda de la génesis'' como totalidad del devenir humano).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64453, 'spa', 'Engendrar, procrear', 'Engendrar o procrear un hijo, con el padre como agente. Es el verbo genealogico por excelencia de Mt 1:2-16, donde la formula ''A engendro a B'' encadena cuarenta y dos generaciones. Tambien describe la generacion unica del Hijo por parte de Dios (Heb 1:5, citando Sal 2:7). Las 49 apariciones se concentran en genealogias y pasajes cristologicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64454, 'spa', 'Nacer, venir a la existencia', 'Nacer o venir a la existencia (voz pasiva/media), con el nacido como sujeto. El nacimiento fisico aparece en Mt 2:1 (''Jesus, habiendo nacido en Belen''), mientras que el renacimiento espiritual domina en Juan 3 y 1 Juan (''nacido de Dios,'' ''nacido del Espiritu''). Las 44 apariciones abarcan desde el parto literal hasta la regeneracion divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64471, 'spa', 'Dar a luz, parir', 'Dar a luz o parir un hijo, con la madre como agente. Lucas 1:13 (''Elisabet te dara a luz un hijo'') y Juan 16:21 (''la mujer cuando da a luz'') destacan el papel materno. La expresion espanola ''dar a luz'' capta bellamente la imagen de traer un nino a la luz del dia. Solo cuatro apariciones llevan este sentido especificamente maternal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64482, 'spa', 'Fruto, producto', 'Fruto agrícola, producto o cosecha: lo que la tierra o la vid produce. Jesús emplea la expresión «fruto de la vid» en la Última Cena para referirse al vino (Mateo 26:29; Marcos 14:25; Lucas 22:18), y Pablo habla de Dios multiplicando los «frutos» de la justicia de los corintios (2 Corintios 9:10). Las traducciones al español usan «fruto» y «frutos», enfatizando el producto concreto de la cosecha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64483, 'spa', 'Descendencia, camada', 'Descendencia o camada, usado metafóricamente en la punzante expresión «camada de víboras» (γεννήματα ἐχιδνῶν). Juan el Bautista (Mateo 3:7; Lucas 3:7) y Jesús (Mateo 12:34; 23:33) aplican este epíteto a quienes cuyo carácter revela un linaje corrupto. El español alterna entre «crías» (las crías de un animal) y «engendros» (algo engendrado), destacando la metáfora biológica de procedencia venenosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64486, 'spa', 'Región de Genesaret', 'Mateo 14:34 y Marcos 6:53 describen el desembarco en «la tierra de Genesaret» después de la alimentación milagrosa y la caminata de Jesús sobre el agua. Lucas 5:1 se refiere al «lago de Genesaret» durante la pesca milagrosa. La fertilidad y accesibilidad de la región la convirtieron en un punto clave del ministerio de Jesús en Galilea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64487, 'spa', 'Nacidos de mujeres', 'Mateo 11:11 y Lucas 7:28 contienen la evaluación idéntica de Jesús: ''Entre los nacidos (gennētois) de mujeres no se ha levantado nadie más grande que Juan el Bautista; sin embargo, el que es más pequeño en el reino de los cielos es mayor que él.'' El español ''nacidos'', francés ''né'' y formas alemanas mantienen este significado relacionado con el nacimiento. El dativo plural modifica ''mujeres,'' creando la frase ''nacidos-de mujeres.'' Jesús usa este modismo hebreo para enfatizar la humanidad universal mientras exalta a Juan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64488, 'spa', 'Clase, tipo o genero de cosas', 'Clase, tipo o genero de cosas: una agrupacion categorica basada en caracteristicas compartidas, no en descendencia biologica. Con 6 apariciones, este sentido clasifica variedades: ''todo genero de peces'' en la parabola de la red (Mt 13:47), ''generos de lenguas'' entre los dones espirituales (1 Co 12:10, 28) y ''este genero (de demonio) no sale sino con oracion'' (Mt 17:21; Mr 9:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64489, 'spa', 'Linaje familiar, descendencia o progenie', 'Linaje familiar, descendencia o progenie: el grupo de personas emparentadas por nacimiento, parentesco o linea ancestral. Con 11 apariciones, es el sentido dominante en el NT: Bernabe como ''levita, natural de Chipre'' (Hch 4:36), la familia de Jose revelada a Faraon (Hch 7:13), el decreto de Faraon contra la raza israelita (Hch 7:19) y la apelacion de Pablo a los ''hijos del linaje de Abraham'' (Hch 13:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64495, 'spa', 'Raza, nacion o pueblo que comparte ascendencia etnica o identidad nacional comun', 'Raza, nacion o pueblo que comparte ascendencia etnica o identidad nacional comun. Con 4 apariciones, este sentido identifica al pueblo o los compatriotas como colectivo: la mujer sirofenicia es ''griega, sirofenicia de raza'' (Mr 7:26), Pablo enumera ''peligros de los de mi nacion'' (2 Co 11:26), su celo superaba a otros ''en mi raza'' (Ga 1:14), y su pedigri es ''del linaje de Israel'' (Fil 3:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64501, 'spa', 'Habitantes de Gergesa', 'Las tres ocurrencias (Marcos 5:1, Lucas 8:26, 37) se refieren a los habitantes de la region donde Jesus sano al endemoniado que vivia entre los sepulcros. Los indicadores geograficos del relato —cruzar el mar, la pendiente escarpada, la piara de cerdos— corresponden a la ubicacion en la orilla oriental. La diversidad de variantes textuales refleja la complejidad de la transmision manuscrita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64504, 'spa', 'El sentido figurado', 'El sentido figurado: experimentar o participar de algo de manera personal y directa, especialmente en la expresión ''gustar la muerte'' (Mt 16:28; Mr 9:1; Heb 2:9), que significa padecer la muerte. También se aplica a gustar ''el don celestial'' y ''la bondad del Señor'' (Heb 6:4-5; 1 P 2:3). El español ''gustar'' conserva la misma extensión metafórica del sabor físico a la experiencia vivencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64505, 'spa', 'El sentido literal y físico de probar o comer alimentos y bebidas', 'El sentido literal y físico de probar o comer alimentos y bebidas. En Mt 27:34 Jesús prueba el vino agriado pero se niega a beberlo; en Jn 2:9 el maestresala prueba el agua convertida en vino. Hch 10:10 y 20:11 lo usan para tomar una comida, y Col 2:21 cita prohibiciones ascéticas: ''no manejes, no gustes, no toques.'' Las traducciones al español como ''gustes'' y ''habiendo gustado'' reflejan este sentido concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64516, 'spa', 'Labrador arrendatario o viñador que trabaja tierra alquilada, particularmente un', 'Labrador arrendatario o viñador que trabaja tierra alquilada, particularmente una viña. Predomina en las parábolas sinópticas de la viña (Mt 21:33-41, Mr 12:1-9, Lc 20:9-16), donde los γεωργοί son arrendatarios que deben al propietario una parte de la cosecha. En Jn 15:1, el Padre mismo es llamado el γεωργός que poda los sarmientos para que den más fruto, elevando la imagen agrícola a alegoría del cuidado divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64518, 'spa', 'Agricultor en el sentido agrícola general, quien cultiva la tierra sin la relaci', 'Agricultor en el sentido agrícola general, quien cultiva la tierra sin la relación específica de viñedo o arrendamiento. Pablo lo usa en 2 Ti 2:6, donde el agricultor que trabaja con esfuerzo merece ser el primero en participar de los frutos, como metáfora del trabajo ministerial. Santiago 5:7 presenta al labrador que espera pacientemente la lluvia y el fruto precioso como modelo para los creyentes que aguardan el regreso del Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64521, 'spa', 'tierra, el mundo', 'La tierra como totalidad: el mundo o planeta creado, frecuentemente en contraste con el cielo. ''Hágase tu voluntad, así en la tierra como en el cielo'' (Mt 6:10), ''los mansos heredarán la tierra'' (Mt 5:5) y ''hasta que pasen el cielo y la tierra'' (Mt 5:18) invocan γῆ como la totalidad del ámbito terrestre. Este sentido cósmico es el dominante (176 apariciones). Cada lengua meta usa su término geográfico más amplio: español tierra, alemán Erde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64522, 'spa', 'tierra, territorio, región', 'Una tierra, territorio, país o región específicos — frecuentemente un lugar con nombre propio como ''la tierra de Israel'' (Mt 2:20–21), ''la tierra de Judá'' (Mt 2:6) o ''la tierra de Zabulón y Neftalí'' (Mt 4:15). El vocablo se estrecha de lo global a la geografía política, designando un área delimitada con identidad propia. El árabe arḍ seguido de nombre propio, el francés la terre de y el alemán das Land reflejan este uso territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64524, 'spa', 'suelo, tierra, polvo', 'La superficie física del suelo o la tierra como sustancia tangible, especialmente en contextos agrícolas y de sepultura. La semilla que cayó en pedregales ''no tenía profundidad de tierra'' (Mc 4:5); un labrador esparce semilla ''en la tierra'' (Mc 4:26). El español tierra y el francés terre en su registro agrícola (''buena tierra'') captan este sentido concreto y táctil: γῆ como humus, sustrato de cultivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64528, 'spa', 'orilla, tierra firme', 'Tierra firme en oposición al mar o al agua — la orilla o costa. En Lucas 5:3 Jesús pide a Simón que se aparte ''de tierra'', y en Lucas 5:11 los discípulos sacan sus barcas ''a tierra''. Este sentido marítimo, que refleja el uso clásico griego (γῆ opuesto a θάλασσα), aparece solo dos veces en el corpus. El francés terre en la expresión náutica mettre pied à terre y el español ''tocar tierra'' preservan esta misma oposición mar/tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64534, 'spa', 'Envejecer literalmente o figuradamente', 'Juan 21:18 usa el subjuntivo aoristo en la profecía de Jesús: ''cuando envejezcas (γηράσῃς), extenderás tus manos,'' prediciendo la muerte de Pedro en la vejez por crucifixión. Hebreos 8:13 emplea el participio presente pasivo: lo que está ''envejeciendo y haciéndose viejo (γηράσκον)'' está listo para desaparecer, refiriéndose a la obsolescencia del antiguo pacto. El español ''envejezcas/encaneciendo'', francés ''vieillir'' y alemán ''altern'' capturan tanto el sentido literal de envejecimiento físico como el figurado de obsolescencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64535, 'spa', 'llegar a ser, hacerse', 'Sentido básico de transición de un estado a otro: ''convertirse en'', ''hacerse'', ''volverse''. Con predicado nominal: ''llegó a ser rey'', ''se hizo discípulo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64536, 'spa', 'suceder, acontecer', 'Verbo de ocurrencia pura: ''ocurrir'', ''suceder'', ''tener lugar''. Común en fórmulas narrativas como ἐγένετο δέ (''y sucedió que...'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64543, 'spa', 'ser hecho, ser creado', 'Uso teológico fundamental en contextos de creación: ''ser hecho'', ''ser creado'', ''llegar a existir''. Juan 1:3 ''todas las cosas por él fueron hechas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64548, 'spa', 'nacer', 'Uso específico para el nacimiento: ''nacer'', ''venir al mundo''. Paralelo al uso de γεννάω pero con énfasis en el evento de surgir a la existencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64549, 'spa', 'venir, llegar, presentarse', 'Matiz de movimiento hacia un lugar o situación: ''llegar'', ''presentarse'', ''aparecer''. Puede combinarse con preposiciones locativas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64561, 'spa', 'resultar ser, mostrarse', 'Sentido de manifestación o prueba: ''resultar'', ''mostrarse'', ''revelarse como''. Con predicados adjetivales: ''se mostró fiel''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64592, 'spa', 'copulativo de transición', 'Función como verbo copulativo en construcciones perifrásticas o enfáticas, especialmente con participios. Menos estático que εἰμί.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64615, 'spa', 'cumplirse, realizarse', 'Uso en contextos de profecía y promesa: ''cumplirse'', ''realizarse'', ''hacerse realidad''. El verbo del cumplimiento escatológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64676, 'spa', 'conocer, saber', 'Conocer por experiencia, relación o trato personal: el sentido activo general que abarca la gran mayoría de las ocurrencias (196x). Es un saber comprometido y vivencial: Jesús conoce a sus ovejas (Jn 10:14, 27), los discípulos conocen la verdad (Jn 8:32) y los creyentes conocen a Dios (1 Jn 4:8). El español distingue entre «conocer» (trato personal) y «saber» (información), pero ambos convergen aquí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64689, 'spa', 'ser conocido, darse a conocer', 'Formas pasivas y medio-pasivas en las que el sujeto es objeto del conocimiento ajeno. «Nada hay encubierto que no haya de ser manifestado» (Mt 10:26; Lc 12:2). Un árbol «se conoce» por su fruto (Mt 12:33; Lc 6:44). La pasiva frecuentemente conlleva fuerza divina: es Dios quien hace que algo sea conocido. El español «ser conocido» y «fue dado a conocer» reflejan esta orientación pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64695, 'spa', 'entender, comprender', 'Captar el significado de algo en profundidad, más allá de la mera familiaridad. Los discípulos «no entendían» lo que Jesús decía sobre la levadura de los fariseos (Jn 8:27, 43) ni «comprendían» el sentido de la parábola (Jn 10:6). Pero tras la resurrección «entendieron» lo que las Escrituras anunciaban (Jn 12:16). Este sentido subraya la comprensión cognitiva plena, no solo el contacto con la información.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64715, 'spa', 'percibir, sentir', 'Percepción directa, física o intuitiva: conciencia inmediata y corporal. En Mr 5:29 la mujer con flujo de sangre «sintió en su cuerpo que estaba sanada». No es comprensión intelectual ni conocimiento relacional, sino percepción visceral y encarnada. El aoristo marca el instante del reconocimiento: percibió de golpe la curación. El español «sintió» y «percibió» captan bien este matiz sensorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64722, 'spa', 'enterarse, descubrir', 'El momento ingresivo de llegar a saber algo antes desconocido. Cuando Jesús pregunta «¿cuántos panes tenéis? Id a ver» (Mr 6:38), el verbo capta la transición de la ignorancia al conocimiento. En Hch 17:13 los judíos de Tesalónica «se enteraron» de que Pablo predicaba en Berea. El aoristo marca puntualmente el instante en que se adquiere la información nueva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64723, 'spa', 'haber conocido, reconocer', 'Sentido perfectivo donde el conocimiento previo conlleva el peso de una relación anterior y sus obligaciones. Romanos 1:21 afirma que la humanidad, «habiendo conocido a Dios, no le glorificaron como a Dios». El participio γνόντες tiene fuerza concesiva: a pesar de poseer verdadero conocimiento de Dios por medio de la creación, se negaron a honrarlo. El español «habiendo conocido» conserva esta carga de reconocimiento desatendido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64763, 'spa', 'Dulce o fresco', 'De sabor dulce o fresco, describe una cualidad agradable del gusto o del agua en contraste con lo amargo o salado. Se usa en Santiago 3:11-12 del agua que no puede ser dulce (γλυκύς) y salobre a la vez, y en Apocalipsis 10:9-10 del rollo dulce como la miel. Las traducciones convergen en el sentido literal de sabor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64764, 'spa', 'Lengua (organo fisico)', 'El organo fisico de la lengua, usado en contextos de sanacion, habla y sensacion corporal. Pasajes clave incluyen la sanacion del sordomudo (Mc 7:33, 35), la restauracion del habla de Zacarias (Lc 1:64) y el tormento del rico (Lc 16:24). Santiago la emplea vividamente como un ''fuego'' que corrompe todo el cuerpo (Stg 3:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64766, 'spa', 'Lenguas, don carismatico', 'Hablar en lenguas: expresion capacitada por el Espiritu Santo en idiomas no aprendidos o habla extatica. Fenomeno distintivamente neotestamentario, las traducciones pasan de la simple ''lengua'' a frases preposicionales como ''en lenguas,'' senalando el contexto del don carismatico-espiritual. Central en Pentecostes (Hch 2:3-4), en la casa de Cornelio (Hch 10:46) y en la ensenanza paulina sobre los dones (1 Co 12-14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64769, 'spa', 'Bolsa común del dinero', 'Juan 12:6 explica la falsa preocupación de Judas por los pobres: ''dijo esto no porque le importaran los pobres, sino porque era ladrón, y teniendo la bolsa (glossokomon) solía tomar lo que se ponía en ella.'' Juan 13:29 nota que ''algunos pensaban, porque Judas tenía la bolsa,'' Jesús le estaba diciendo que comprara provisiones. El español ''bolsa'', francés ''bourse'' y alemán ''Geldbeutel'' todos hacen referencia a un contenedor para dinero. Ambos pasajes presentan a Judas como el tesorero del grupo apostólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64771, 'spa', 'Genuino o legítimo', 'Genuino, verdadero o legítimo; describe lo auténtico en carácter o relación, opuesto a lo falso o nominal. Pablo lo aplica a personas — Timoteo como ''hijo genuino'' en la fe (1 Tim 1:2), un ''verdadero compañero'' (Fil 4:3) — y a cualidades como la autenticidad del amor (2 Cor 8:8). Transmite calidez afectiva junto con legitimidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64774, 'spa', 'Opinión, juicio, consejo', 'Opinión, juicio o consejo: un punto de vista personal y meditado que se ofrece sobre un asunto, especialmente cuando se expresa una perspectiva sin autoridad vinculante absoluta. Pablo da su «parecer» (γνώμην) sobre los solteros (1 Corintios 7:25) y se considera digno de confianza al ofrecer su «opinión» (1 Corintios 7:40). Apela a que los corintios estén unidos en un mismo «sentir y parecer» (1 Corintios 1:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64775, 'spa', 'Propósito, resolución', 'Propósito, resolución o intención determinada: una determinación firme y a menudo colectiva de actuar. En Apocalipsis 17:13, los diez reyes tienen «un mismo propósito» (μίαν γνώμην) al entregar su poder a la bestia, y Dios mismo ha puesto en sus corazones ejecutar su «propósito» (γνώμην, Apocalipsis 17:17). El desplazamiento de opinión personal a resolución colectiva o divina es notable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64779, 'spa', 'El sentido causativo activo', 'El sentido causativo activo: dar a conocer, revelar o declarar informacion a otros. Predomina en el uso neotestamentario, abarcando los actos reveladores de Jesus (Jn 15:15; 17:26), la proclamacion apostolica (Col 1:27) y las peticiones en oracion (Fil 4:6). Lucas 2:15-17 muestra a los pastores dando a conocer el mensaje angelico, mientras que Efesios 6:21 lo usa para noticias personales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64781, 'spa', 'La contrapartida pasiva', 'La contrapartida pasiva: ser dado a conocer, ser revelado o manifestado. Central en la teologia paulina del misterio: Romanos 16:26 y Efesios 3:3-10 describen el plan eterno de Dios ahora dado a conocer a las naciones. La voz pasiva presenta a los receptores humanos como aquellos a quienes llega la verdad divina, no como quienes la descubren por si mismos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64792, 'spa', 'Un sentido medio o intransitivo poco frecuente en Filipenses 1', 'Un sentido medio o intransitivo poco frecuente en Filipenses 1:22, donde Pablo podria querer decir ''no se'' o ''no puedo discernir'' que elegir entre la vida y la muerte. Esto se alinea con el sentido del griego clasico de ''adquirir conocimiento de'' o ''familiarizarse con,'' una direccion semantica mayormente ausente del Nuevo Testamento pero atestiguada en Sofocles y Platon.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64797, 'spa', 'Conocimiento cognitivo y espiritual, especialmente el conocimiento salvador de D', 'Conocimiento cognitivo y espiritual, especialmente el conocimiento salvador de Dios y de Cristo. Lucas lo introduce como ''conocimiento de salvacion'' (Lc 1:77) y ''llave del conocimiento'' (Lc 11:52). Pablo lo desarrolla mas ampliamente: un don espiritual (1 Co 12:8), fuente potencial de orgullo que debe ser templada por el amor (1 Co 8:1-2), y fragancia de Cristo difundida a traves del ministerio apostolico (2 Co 2:14). Pedro corona el tema exhortando a crecer en la gracia y el conocimiento del Senor (2 P 3:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64801, 'spa', 'El sentido adjetival', 'El sentido adjetival: conocido, reconocido o notable. Se usa predicativamente (''esto se ha hecho conocido a todos,'' Hch 4:16) o atributivamente (''un milagro notable,'' Hch 4:16). En Jn 18:15-16 identifica a alguien personalmente conocido por un individuo específico: el discípulo conocido del sumo sacerdote. El español ''conocido'' traduce este sentido con exactitud. Con trece apariciones en Hechos y Juan, este sentido domina el NT.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64804, 'spa', 'El sentido sustantivado', 'El sentido sustantivado: conocidos, personas familiares a alguien, usado como equivalente nominal del clásico γνώριμοι. Lucas lo emplea dos veces: en 2:44, José y María buscan entre sus ''conocidos'' (parientes y círculo familiar), y en 23:49, los ''conocidos'' de Jesús permanecen observando la crucifixión desde lejos. El español ''conocidos'' capta esto con precisión. El paso de adjetivo a sustantivo marca un uso distintivamente lucano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64807, 'spa', 'Murmurar, refunfuñar', 'Murmurar, refunfuñar o gruñir con descontento, expresando insatisfacción mediante quejas en voz baja dirigidas contra alguien o algo. Las ocho apariciones en el NT comparten este sentido: ya sean los jornaleros de la viña protestando contra la generosidad del amo (Mateo 20:11), los fariseos objetando que Jesús comparta mesa con pecadores (Lucas 5:30), o la multitud judía disputando la afirmación de Jesús de haber descendido del cielo (Juan 6:41, 43, 61).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64813, 'spa', 'Murmuración o queja', 'Murmuración, queja susurrada o descontento expresado en voz baja dentro de una comunidad, en contraste con la protesta abierta. En Juan 7:12 caracteriza los cuchicheos divididos sobre Jesús entre la multitud; en Hechos 6:1 la queja de los helenistas por la distribución de alimentos. Pablo y Pedro advierten contra ella como algo corrosivo para la vida comunitaria (Fil 2:14; 1 Pe 4:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64816, 'spa', 'Sitio de la crucifixion', 'Mateo 27:33, Marcos 15:22 y Juan 19:17 emplean el nombre arameo al narrar la crucifixion. Los evangelistas ofrecen la glosa interpretativa ''lugar de la calavera'' para que los lectores griegos comprendan el termino semitico. La conservacion del nombre arameo incluso en textos griegos subraya la importancia reverente de este topografico en la memoria cristiana primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64817, 'spa', 'Ciudad destruida por Dios', 'La ciudad de Gomorra, destruida por Dios junto con Sodoma como juicio definitivo. En el NT siempre aparece emparejada con Sodoma en contextos de advertencia: Jesús la invoca contra pueblos inhospitalarios (Mt 10:15; Mr 6:11), Pablo cita Isaías 1:9 sobre la preservación de un remanente (Ro 9:29), y Pedro y Judas la presentan como paradigma de castigo para los impíos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64818, 'spa', 'Cargamento comercial', 'Hechos 21:3 menciona un barco ''descargando su cargamento'' en Tiro. Apocalipsis 18:11-12 emplea el termino al lamentar que los mercaderes ya no pueden vender ''su carga'' a la Babilonia caida, seguido de un inventario detallado de bienes de lujo. El pasaje de Apocalipsis amplifica el sentido comercial del termino al enumerar mercancias que van desde oro y seda hasta esclavos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64819, 'spa', 'Los padres como unidad familiar', 'Los padres como unidad familiar: padre y madre considerados juntos. Las 20 apariciones en el NT usan el plural para designar a ambos progenitores, ya sea en narraciones sobre la infancia de Jesús (Lc 2:27, 41, 43), instrucciones sobre honrar a los padres, o advertencias apocalípticas de traición familiar (Mt 10:21; Mr 13:12). La traducción multilingüe consistente (inglés ''parents,'' español ''padres,'' alemán ''Eltern'') confirma que el término señala a la pareja parental como unidad, no a un solo progenitor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64821, 'spa', 'La rodilla como parte del cuerpo involucrada en el acto de arrodillarse, usada c', 'La rodilla como parte del cuerpo involucrada en el acto de arrodillarse, usada casi exclusivamente en contextos de adoración, oración o humilde súplica. Abarca caer de rodillas ante Jesús (Mr 1:40; 10:17; Lc 5:8; Mr 15:19 en burla), arrodillarse en oración (Lc 22:41; Hch 7:60; 9:40; 20:36; 21:5) y la confesión universal de que toda rodilla se doblará (Ro 14:11; Fil 2:10; Ef 3:14). Hebreos 12:12 usa la imagen de rodillas debilitadas para exhortar a la perseverancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64825, 'spa', 'Arrodillarse ante alguien', 'Caer de rodillas o arrodillarse ante alguien en señal de súplica, reverencia o mofa. La postura física lleva una carga emocional intensa: la desesperación de un padre por la sanidad de su hijo (Mat 17:14), la súplica de un leproso (Mar 1:40), la sinceridad de un buscador (Mar 10:17), y la genuflexión burlona de los soldados (Mat 27:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64826, 'spa', 'El código escrito de la Ley mosaica como norma externa y constrictiva', 'El código escrito de la Ley mosaica como norma externa y constrictiva: la ''letra'' teológica de Pablo contrastada con el Espíritu. En Romanos 2:27-29 la circuncisión ''en la letra'' se opone a la circuncisión del corazón, y Romanos 7:6 declara la liberación de servir ''en la vejez de la letra.'' La declaración culminante aparece en 2 Corintios 3:6: ''la letra mata, pero el Espíritu vivifica.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64828, 'spa', 'Letras individuales del alfabeto o caracteres escritos', 'Letras individuales del alfabeto o caracteres escritos: el sentido más básico y físico. Lucas 23:38 señala que la inscripción sobre la cruz estaba escrita ''en letras'' griegas, latinas y hebreas. Pablo llama la atención sobre las ''grandes letras'' que escribe de su propia mano (Gá 6:11), y 2 Corintios 3:7 describe el ministerio de muerte ''grabado con letras en piedra.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64829, 'spa', 'Un documento escrito, específicamente un certificado de deuda o registro financi', 'Un documento escrito, específicamente un certificado de deuda o registro financiero. En la parábola del administrador astuto de Jesús, se dice a los deudores que tomen su ''documento'' y modifiquen rápidamente la cantidad (Lc 16:6-7). Este sentido comercial conecta con el uso grecorromano más amplio de γράμμα para cualquier instrumento escrito oficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64830, 'spa', 'Escritos o Escrituras', 'Escritos o Escrituras: un cuerpo de textos sagrados autoritativos. Jesús pregunta: ''si no creéis a sus [de Moisés] escritos, ¿cómo creeréis a mis palabras?'' (Jn 5:47). En Jn 7:15 la multitud se asombra de que Jesús conozca ''las letras'' (las Escrituras) sin formación académica. A Timoteo se le elogia por conocer ''las sagradas escrituras'' desde la niñez (2 Ti 3:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64831, 'spa', 'Carta de correspondencia', 'Carta de correspondencia: una epístola o comunicación oficial enviada entre partes. Hechos 28:21 registra que los líderes judíos en Roma no recibieron ''cartas'' de Judea acerca de Pablo. Este sentido se superpone con ἐπιστολή pero enfatiza el objeto escrito físico más que el acto de enviar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64833, 'spa', 'Erudición, educación o conocimiento literario adquirido mediante lectura extensa', 'Erudición, educación o conocimiento literario adquirido mediante lectura extensa. Festo exclama: ''¡tus muchas letras te están volviendo loco!'' (Hch 26:24), usando γράμματα para referirse a la sabiduría acumulada. Esta extensión metonímica, de los textos escritos al conocimiento obtenido al estudiarlos, es compartida por el español ''letras,'' que puede significar tanto ''caracteres'' como ''saber.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64835, 'spa', 'Escriba, experto en la Ley', 'Escriba judio, experto y maestro de la Ley mosaica. Con 63 apariciones, este sentido domina el uso neotestamentario. Las traducciones emplean consistentemente vocabulario religioso especializado — en espanol ''escribas,'' en aleman Schriftgelehrter (''docto en las Escrituras'') — en lugar del generico ''secretario,'' confirmando el significado tecnico-religioso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64837, 'spa', 'Secretario municipal', 'Funcionario civico o secretario municipal, especificamente el secretario administrativo de una ciudad griega. Atestiguado solo en Hechos 19:35, donde el γραμματεύς de Efeso interviene para aquietar a la multitud amotinada contra Pablo. El espanol ''secretario'' capta la naturaleza administrativa, no religiosa, de este cargo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64841, 'spa', 'Escritura sagrada', 'Los escritos sagrados autoritativos, principalmente la Biblia hebrea tal como se cita a lo largo del Nuevo Testamento. El singular γραφή introduce tipicamente un pasaje especifico (''esta Escritura,'' Mc 12:10; Jn 19:37), mientras que el plural αἱ γραφαί se refiere al canon escritural en su conjunto (''errais, ignorando las Escrituras,'' Mt 22:29). Jesus fundamenta su mision en la necesidad del cumplimiento escritural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64850, 'spa', 'escrito está (cita escritural)', 'La fórmula teológica del perfecto pasivo γέγραπται, usada para introducir la Escritura con autoridad. Jesús la emplea tres veces contra las tentaciones de Satanás (Mt 4:4, 6, 7, 10) y aparece en toda la argumentación de estilo rabínico de las Epístolas. El perfecto es clave: indica que lo inscrito permanece vigente como norma permanente. El español «Escrito está» reproduce fielmente tanto el aspecto como la solemnidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64851, 'spa', 'escrito, registrado', 'Participios pasivos y aoristos pasivos que describen el estado resultante de un texto: algo que existe en forma escrita. Jesús encuentra «el lugar donde estaba escrito» (Lc 4:17), y Apocalipsis se refiere repetidamente a nombres «escritos en el libro de la vida» (Ap 20:15; 21:27). El foco no está en el acto de escribir sino en la inscripción consumada como hecho permanente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64852, 'spa', 'escribir, redactar', 'Sentido activo de componer una carta, documento o decreto. Moisés escribe mandamientos, Pablo redacta epístolas, Pilato ordena un título para la cruz. Lucas 1:3 muestra al evangelista decidiendo «escribir un relato ordenado», y Lc 16:6-7 presenta a un deudor reescribiendo apresuradamente un pagaré. Abarca toda comunicación escrita intencionada por un autor humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64869, 'spa', 'ser escrito, registrarse', 'Infinitivos y subjuntivos pasivos que expresan la posibilidad o el propósito de escribir. Juan 21:25 declara que si todo lo que Jesús hizo fuera escrito, el mundo no podría contener los libros. Primera Tesalonicenses 5:1 dice que no hay necesidad «de que se os escriba». Este sentido infrecuente desplaza la atención del autor o del texto al acto hipotético o potencial de la escritura misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64882, 'spa', 'Vigilancia espiritual y moral', 'Vigilancia espiritual y moral: estar alerta, atento y en guardia en preparacion para el retorno del Senor o contra el peligro moral. Este sentido dominante (21 de 23 apariciones) abarca las advertencias escatologicas del Discurso del Monte de los Olivos (Mt 24:42; 25:13), la vigilia en Getsemani (Mt 26:38-41) y las exhortaciones apostolicas (1 Co 16:13; 1 Ts 5:6; Ap 3:2-3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64884, 'spa', 'Vigilia fisica literal', 'Vigilia fisica literal: permanecer despierto durante la noche, particularmente como guardia contra la intrusion. Limitado a las parabolas del dueno de casa en Mt 24:43 y Lc 12:39, donde el amo habria velado si hubiera sabido la hora del ladron. Este sentido concreto y corporal se distingue de la vigilancia metaforica que domina el resto de los usos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64893, 'spa', 'Entrenar o ejercitar', 'Entrenar, ejercitar o disciplinar mediante práctica sostenida, originalmente del entrenamiento atlético y metafóricamente de la formación espiritual o moral. Pablo insta a Timoteo a ejercitarse en la piedad (1 Tim 4:7); Hebreos habla de sentidos entrenados por la práctica (Heb 5:14) y del fruto de la disciplina para quienes son ejercitados por ella (Heb 12:11). Incluso negativamente, 2 Pedro 2:14 describe corazones entrenados en la avaricia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64896, 'spa', 'Sin ropa o sin cobertura adecuada, abarcando desde la desnudez literal hasta est', 'Sin ropa o sin cobertura adecuada, abarcando desde la desnudez literal hasta estar insuficientemente vestido. En los Evangelios, describe a quienes necesitan vestimenta (Mt 25:36, 38, 43) y al joven que huyó sin ropa en el arresto de Jesús (Mr 14:51-52). Se extiende metafóricamente a la exposición y vulnerabilidad espiritual (Ap 3:17, ''eres miserable y desnudo''; Heb 4:13, ''desnudo y expuesto'' ante Dios). Pablo lo emplea para el estado del alma sin su revestimiento celestial (2 Co 5:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64898, 'spa', 'Vulnerabilidad y carencia', 'Romanos 8:35 enumera la ''desnudez'' entre las pruebas que no pueden separar a los creyentes del amor de Dios. 2 Corintios 11:27 la incluye en el catalogo de padecimientos apostolicos de Pablo. Apocalipsis 3:18 advierte a la iglesia de Laodicea que obtenga vestiduras blancas ''para cubrir la verguenza de tu desnudez''. El termino abarca desde la privacion material hasta la exposicion espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64901, 'spa', 'mujer, persona femenina', 'Ser humano adulto de sexo femenino, sin referencia específica al estado civil. Se emplea genéricamente para las mujeres que Jesús encuentra: la mujer con hemorragia (Mt 9:20-22), la cananea (Mt 15:22), la mujer con la levadura (Mt 13:33) y como forma de trato (γύναι). El vocativo en Jn 2:4 y 19:26 es respetuoso, no despectivo. Abarca toda mención de una mujer sin implicación matrimonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64904, 'spa', 'esposa, cónyuge', 'Mujer casada en relación con su marido, con énfasis en el vínculo conyugal. «El hombre dejará a su padre y a su madre y se unirá a su mujer» (Mt 19:5; Gn 2:24 LXX). El extenso discurso de Pablo sobre el matrimonio en 1 Corintios 7 y la cuestión de los saduceos sobre la mujer casada con siete hermanos (Lc 20:33) emplean γυνή inequívocamente como «esposa». El español a veces desambigua con «esposa».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64921, 'spa', 'Esquina, ángulo', 'Esquina o ángulo de una estructura, calle o región espacial. La palabra tiene dos aplicaciones principales en el NT bajo un mismo campo semántico: la piedra angular arquitectónica —la piedra crítica en la esquina de un edificio, aplicada cristológicamente en Mateo 21:42, Marcos 12:10, Lucas 20:17, Hechos 4:11 y 1 Pedro 2:7— y la esquina de la calle donde la gente se coloca para orar ostentosamente (Mateo 6:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64924, 'spa', 'David (nombre propio)', 'El nombre propio David, referido al rey de Israel, salmista y ancestro mesianico. Usado historicamente (Mt 1:6; Hch 13:22), como autor atribuido de salmos (Mc 12:36; Heb 4:7) y como portador de titulos cristologicos: ''Hijo de David'' para el Mesias (Mt 1:1; 9:27), ''trono de David'' (Lc 1:32), ''raiz de David'' (Ap 5:5) y ''llave de David'' (Ap 3:7). Transliterado universalmente en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64926, 'spa', 'Estar bajo el control o la aflicción de un demonio, estar endemoniado', 'Estar bajo el control o la aflicción de un demonio, estar endemoniado. Fenómeno exclusivamente evangélico en el NT, aparece en resúmenes sinópticos del ministerio sanador de Jesús (Mt 4:24; Mr 1:32), en relatos específicos de exorcismo (Mt 8:28; 9:32; 12:22; 15:22; Mr 5:15-18; Lc 8:36) y en la acusación contra el propio Jesús (Jn 10:21). El participio δαιμονιζόμενος funciona como sustantivo (''el endemoniado''), indicando dominación espiritual externa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64933, 'spa', 'Demonio, espiritu maligno', 'Ser sobrenatural malevolente o espiritu inmundo que oprime y posee a las personas, expulsado por autoridad divina. Este es el uso dominante en el NT con 62 de 63 apariciones, abarcando las narraciones sinopticas de exorcismo (Mt 7:22; Mc 1:34; Lc 11:14) y pasajes doctrinales. Todas las lenguas principales lo tratan uniformemente: espanol ''demonios,'' frances ''demon,'' aleman ''Damon.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64943, 'spa', 'Deidad pagana, ser divino', 'Deidad pagana o poder divino en el sentido griego clasico, referido a seres sobrenaturales sin implicar necesariamente malevolencia. Este uso raro en el NT aparece solo en Hechos 17:18, donde los filosofos atenienses oyen a Pablo predicar a Jesus y la resurreccion y suponen que es heraldo de ''divinidades extranjeras.'' El espanol ''divinidades'' capta adecuadamente el matiz cultural frente al habitual ''demonios.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64947, 'spa', 'Lágrima, lágrimas (llanto)', 'Lágrima, lágrimas (llanto). Gota o gotas de líquido salino derramadas de los ojos como expresión de dolor, compasión, oración ferviente o angustia emocional. Se usa para las lágrimas pastorales de Pablo (Hechos 20:19, 31; 2 Corintios 2:4; 2 Timoteo 1:4), las lágrimas de la mujer penitente a los pies de Jesús (Lucas 7:38, 44), las oraciones angustiadas de Cristo mismo (Hebreos 5:7; 12:17) y la promesa escatológica de consuelo cuando Dios enjugue toda lágrima (Apocalipsis 7:17; 21:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64951, 'spa', 'Dedo, dedos', 'Dígito de la mano humana, empleado para acciones físicas literales — tocar, señalar, sanar (Marcos 7:33; Juan 8:6; Juan 20:25) — y en expresiones figuradas como ''el dedo de Dios'', que denota poder y agencia divina (Lucas 11:20, evocando Éxodo 8:19). Español ''dedo'', francés ''doigt'' y alemán ''Finger'' confirman un sentido único y unificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64955, 'spa', 'Domar o someter', 'Domar, someter o poner bajo control lo que es salvaje o indómito. Se aplica al endemoniado a quien nadie podía sujetar (Mar 5:4), y Santiago lo utiliza para describir la capacidad humana de domar toda especie animal frente a la incapacidad de domar la lengua (Stg 3:7-8). La imagen evoca el dominio sobre algo feroz e incontrolable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64959, 'spa', 'La antigua ciudad de Damasco en Siria', 'La antigua ciudad de Damasco en Siria. Las quince apariciones neotestamentarias se relacionan con el apóstol Pablo: su misión para arrestar creyentes allí (Hch 9:2), su encuentro con Cristo en el camino (Hch 9:3; 22:6; 26:12), su predicación inicial y su escape (Hch 9:19-25; 2 Co 11:32) y su regreso desde Arabia (Gá 1:17). Funciona como hito geográfico central en la narrativa de la conversión paulina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64960, 'spa', 'Prestar o pedir prestado', 'Prestar dinero o bienes a alguien, o (en voz media) pedir prestado. Jesús invoca este término financiero para redefinir la generosidad: no rechaces al que quiere pedir prestado (Mat 5:42), y presta sin esperar nada a cambio, a diferencia de los pecadores que solo prestan para obtener ganancia recíproca (Luc 6:34-35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64963, 'spa', 'Profeta del fin de los tiempos', 'Este nombre propio aparece exclusivamente en el discurso escatológico de Jesús (Mateo 24:15, Marcos 13:14), donde dirige a los oyentes a ''Daniel el profeta'' como fuente para comprender la ''abominación desoladora''. Las referencias presuponen que la audiencia está familiarizada con las visiones de Daniel sobre los eventos del fin de los tiempos, haciendo del nombre del profeta un atajo para acceder a esos textos proféticos cruciales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64964, 'spa', 'Gastar, expender recursos', 'Gastar o expender dinero, recursos o a uno mismo. Abarca gasto médico infructuoso (Mr 5:26), derroche pródigo (Lc 15:14), apoyo económico práctico (Hch 21:24, gastos nazareos) y entrega sacrificial (2 Co 12:15, donde Pablo combina ''gastaré'' con ''me desgastaré'' para expresar devoción total). Santiago advierte contra gastar en placeres egoístas (Stg 4:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64966, 'spa', 'adversativo ''pero/sin embargo''', 'Uso adversativo que introduce un contraste leve o matiz opuesto a la cláusula anterior, traducido comúnmente como ''pero'' o ''sin embargo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64969, 'spa', 'conectivo/transicional ''y/ahora''', 'Uso conectivo o transicional que marca la continuación del discurso o avance narrativo, traducido como ''y'', ''ahora'', o ''entonces''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64970, 'spa', 'Oración ferviente o súplica dirigida a Dios, con énfasis en la petición sincera ', 'Oración ferviente o súplica dirigida a Dios, con énfasis en la petición sincera dentro de un contexto devocional o de adoración. Ana adora ''con ayunos y δεήσεις'' (Lc 2:37); Pablo hace ''súplica'' por sus lectores (Fil 1:4); la iglesia primitiva ofrece ''oraciones y súplicas'' (1 Ti 2:1). El español ''oración'' y ''súplica'' transmiten el tono reverente de quien se dirige a Dios con necesidad urgente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64972, 'spa', 'Una petición concreta, ruego o solicitud para una necesidad específica', 'Una petición concreta, ruego o solicitud para una necesidad específica. Mientras el sentido 1 enfatiza la postura devocional, este sentido pone en primer plano el contenido: una solicitud definida. En Ef 6:18, los creyentes deben orar ''con toda oración y petición (δέησις),'' y cada δέησις apunta a una necesidad concreta. Fil 4:6 instruye: ''sean dadas a conocer vuestras peticiones (δεήσεις) delante de Dios.'' El español ''petición'' y ''ruego'' captan esta fuerza de solicitud formal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64982, 'spa', 'es necesario, debe', 'Expresión impersonal de necesidad — divina, lógica o moral — que significa «es necesario», «se debe» o «es inevitable». Central en las predicciones sinópticas de la Pasión donde Jesús declara que el Hijo del Hombre «debe» padecer (Mt 16:21; Mr 8:31), y en el discurso escatológico donde las guerras «deben» ocurrir (Mt 24:6). Cubre también la necesidad práctica (Hch 5:29, «es necesario obedecer a Dios»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64987, 'spa', 'conviene, es propio', 'Lo que es propio, conveniente o apropiado: expresa decoro u obligación social-moral más que compulsión estricta o designio divino. En Mr 13:14 el paréntesis «entienda el lector» implica lo que se «debería» captar, y 1 Ti 5:13 describe conductas que no son «propias» de mujeres creyentes. Las traducciones pasan a «conviene» o «es debido» (frente al más fuerte «es necesario»), señalando un grado menor de obligación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64995, 'spa', 'Exhibición pública', 'La evidencia revela dos usos distintos pero relacionados: el deseo de José de evitar avergonzar públicamente a María (Mateo 1:19: español ''exhibió,'' francés ''faire un exemple'') y la exhibición pública triunfante de Cristo de los poderes derrotados (Colosenses 2:15: inglés ''made a public show,'' español ''avergonzar públicamente''). Ambos contextos enfatizan la naturaleza pública y visible de la acción, ya sea evitada o realizada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (64996, 'spa', 'Mostrar, exhibir, revelar', 'Mostrar, exhibir, revelar: Hacer que alguien perciba algo, ya sea señalándolo físicamente o descubriendo una verdad oculta. Abarca la exhibición de los reinos por parte de Satanás a Jesús (Mt 4:8), la presentación del leproso ante el sacerdote (Mt 8:4; Mr 1:44), la promesa de Jesús de «obras mayores» (Jn 5:20) y la revelación angélica de visiones apocalípticas a lo largo de Apocalipsis (Ap 1:1; 17:1; 21:10; 22:1). El verbo tiende un puente entre la percepción sensorial y la revelación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65012, 'spa', 'Cobarde o temeroso', 'Cobarde, temeroso o tímido; describe una disposición que se acobarda ante lo que debería enfrentarse con fe o valentía. Jesús reprende a los discípulos aterrados por la tormenta como δειλοί (Mt 8:26; Mr 4:40), vinculando el miedo a la falta de fe. Apocalipsis 21:8 ubica a los cobardes en primer lugar entre los condenados, junto con asesinos y mentirosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65014, 'spa', 'Intensidad extrema', 'Aparece en dos contextos dramáticamente diferentes que comparten el hilo común de intensidad extrema: el centurión describiendo el tormento severo de su siervo paralizado (Mateo 8:6) y la reacción hostil de los líderes religiosos hacia Jesús (Lucas 11:53). Las traducciones consistentemente lo traducen como un intensificador que enfatiza el grado temible o terrible de la condición descrita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65015, 'spa', 'Cenar o comer', 'Cenar o tomar la comida principal de la tarde. Este verbo enmarca momentos comunales y teológicos decisivos: un siervo que prepara la cena (Lc 17:8), la copa de la nueva alianza tomada «después de haber cenado» (Lc 22:20; 1 Co 11:25) y la promesa de Cristo de cenar con quien le abra la puerta (Ap 3:20).');